42	const PROCESSING_FEE = 5;
43	
44	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
45	  sword: 100,
46	  amulet: 60,
47	  staff: 80,
48	  potion: 40,
49	  rune: 25,
50	  moonstone: 25,
51	};
52	
53	const BLOCK_SIZE = 3;
54	const BLOCK_BASE_PREMIUM = 60;
55	
56	const groupByType = (items: Item[]): Item[][] => {
57	  const groups = new Map<string, Item[]>();
58	
59	  for (const item of items) {
60	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
61	  }
62	
63	  return [...groups.values()];
64	};
65	
66	const sumBasePremiums = (items: Item[]): number =>
67	  items.reduce((total, item) => total + BASE_PREMIUM_BY_ITEM_TYPE[item.type], 0);
68	
69	const basePremiumOfGroup = (group: Item[]): number =>
70	  group.length === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : sumBasePremiums(group);
71	
72	const quote = ({ items }: QuoteStep): StepResult => {
73	  const totalBasePremium = groupByType(items)
74	    .map(basePremiumOfGroup)
75	    .reduce((total, groupPremium) => total + groupPremium, 0);
76	
77	  return { premium: totalBasePremium + PROCESSING_FEE };
78	};
