const sum = (amounts: number[]): number =>
  amounts.reduce((total, amount) => total + amount, 0);

const groupByType = (items: Item[]): Item[][] => {
  const groups = new Map<string, Item[]>();

  for (const item of items) {
    const group = groups.get(item.type);
    if (group) group.push(item);
    else groups.set(item.type, [item]);
  }

  return [...groups.values()];
};

const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_ITEM_TYPE[item.type];

const basePremiumOfGroup = (group: Item[]): number =>
  group.length === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : sum(group.map(basePremiumOf));

const quote = ({ items }: QuoteStep): StepResult => {
  const totalBasePremium = sum(groupByType(items).map(basePremiumOfGroup));

  return { premium: totalBasePremium + PROCESSING_FEE };
};
